/// Returns the length of the vector.
fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

/// Takes ownership of a Vec<f32> and returns a new Vec<f32> whose length
/// equals the input length. Here we compute the base‐10 logarithm of each
/// element, but any other element‐wise transformation (or even no change)
/// would also satisfy the length requirement.
fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let mut result = Vec::with_capacity(x.len());
    // Iterating by value over `x` guarantees we never go out of bounds,
    // and at each step `result.len()` equals the number of items processed so far.
    for v in x {
        result.push(v.log10());
    }
    // By construction, `result.len()` == original `x.len()`.
    result
}

fn main() {
    let data = vec![1.0_f32, 10.0, 100.0, 1000.0];
    println!("original length = {}", vec_len(&data));

    let logs = numpy_log10(data);
    println!("new length = {}", vec_len(&logs));
    println!("log10 results = {:?}", logs);
}